34	/**
35	 * An application process ID.
36	 *
37	 * @author Phillip Webb
38	 * @since 2.0.0
39	 */
40	public class ApplicationPid {
41	
42		private static final PosixFilePermission[] WRITE_PERMISSIONS = { PosixFilePermission.OWNER_WRITE,
43				PosixFilePermission.GROUP_WRITE, PosixFilePermission.OTHERS_WRITE };
44	
45		private final @Nullable Long pid;
46	
47		public ApplicationPid() {
48			this.pid = currentProcessPid();
49		}
50	
51		protected ApplicationPid(@Nullable Long pid) {
52			this.pid = pid;
53		}
54	
55		private @Nullable Long currentProcessPid() {
56			try {
57				return ProcessHandle.current().pid();
58			}
59			catch (Throwable ex) {
60				return null;
61			}
62		}
63	
64		/**
65		 * Return if the application PID is available.
66		 * @return {@code true} if the PID is available
67		 * @since 3.4.0
68		 */
69		public boolean isAvailable() {
70			return this.pid != null;
71		}
72	
73		/**
74		 * Return the application PID as a {@link Long}.
75		 * @return the application PID or {@code null}
76		 * @since 3.4.0
77		 */
78		public @Nullable Long toLong() {
79			return this.pid;
80		}
81	
82		@Override
83		public boolean equals(Object obj) {
84			if (obj == this) {
85				return true;
86			}
87			if (obj instanceof ApplicationPid other) {
88				return ObjectUtils.nullSafeEquals(this.pid, other.pid);
89			}
90			return false;
91		}
92	
93		@Override
94		public int hashCode() {
95			return ObjectUtils.nullSafeHashCode(this.pid);
96		}
97	
98		@Override
99		public String toString() {
100			return (this.pid != null) ? String.valueOf(this.pid) : "???";
101		}
102	
103		/**
104		 * Write the PID to the specified file.
105		 * @param file the PID file
106		 * @throws IllegalStateException if no PID is available.
107		 * @throws IOException if the file cannot be written
108		 */
109		public void write(File file) throws IOException {
110			Assert.state(this.pid != null, "No PID available");
111			Path path = file.toPath();
112			createParentDirectory(path);
113			if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
114				assertCanOverwrite(path);
115			}
116			Files.writeString(path, this.pid.toString(), StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.CREATE,
117					LinkOption.NOFOLLOW_LINKS);
118		}
119	
120		private void createParentDirectory(Path path) throws IOException {
121			Path parent = path.getParent();
122			if (parent != null) {
123				Files.createDirectories(parent);
124			}
125		}
126	
127		private void assertCanOverwrite(Path file) throws IOException {
128			if (!Files.isWritable(file) || !canWritePosixFile(file)) {
129				throw new FileNotFoundException(file.toString() + " (permission denied)");
130			}
131		}
