31	
32	/**
33	 * {@link PropertyResolver} for {@link AnsiStyle}, {@link AnsiColor},
34	 * {@link AnsiBackground} and {@link Ansi8BitColor} elements. Supports properties of the
35	 * form {@code AnsiStyle.BOLD}, {@code AnsiColor.RED} or {@code AnsiBackground.GREEN}.
36	 * Also supports a prefix of {@code Ansi.} which is an aggregation of everything (with
37	 * background colors prefixed {@code BG_}).
38	 * <p>
39	 * ANSI 8-bit color codes can be used with {@code AnsiColor} and {@code AnsiBackground}.
40	 * For example, {@code AnsiColor.208} will render orange text.
41	 * <a href="https://en.wikipedia.org/wiki/ANSI_escape_code">Wikipedia</a> has a complete
42	 * list of the 8-bit color codes that can be used.
43	 *
44	 * @author Phillip Webb
45	 * @author Toshiaki Maki
46	 * @since 1.3.0
47	 */
48	public class AnsiPropertySource extends PropertySource<AnsiElement> {
49	
50		private static final Iterable<Mapping> MAPPINGS;
51	
52		static {
53			List<Mapping> mappings = new ArrayList<>();
54			mappings.add(new EnumMapping<>("AnsiStyle.", AnsiStyle.class));
55			mappings.add(new EnumMapping<>("AnsiColor.", AnsiColor.class));
56			mappings.add(new Ansi8BitColorMapping("AnsiColor.", Ansi8BitColor::foreground));
57			mappings.add(new EnumMapping<>("AnsiBackground.", AnsiBackground.class));
58			mappings.add(new Ansi8BitColorMapping("AnsiBackground.", Ansi8BitColor::background));
59			mappings.add(new EnumMapping<>("Ansi.", AnsiStyle.class));
60			mappings.add(new EnumMapping<>("Ansi.", AnsiColor.class));
61			mappings.add(new EnumMapping<>("Ansi.BG_", AnsiBackground.class));
62			MAPPINGS = Collections.unmodifiableList(mappings);
63		}
64	
65		private final boolean encode;
66	
67		/**
68		 * Create a new {@link AnsiPropertySource} instance.
69		 * @param name the name of the property source
70		 * @param encode if the output should be encoded
71		 */
72		public AnsiPropertySource(String name, boolean encode) {
73			super(name);
74			this.encode = encode;
75		}
76	
77		@Override
78		public @Nullable Object getProperty(String name) {
79			if (StringUtils.hasLength(name)) {
80				for (Mapping mapping : MAPPINGS) {
81					String prefix = mapping.getPrefix();
82					if (name.startsWith(prefix)) {
83						String postfix = name.substring(prefix.length());
84						AnsiElement element = mapping.getElement(postfix);
85						if (element != null) {
86							return (this.encode) ? AnsiOutput.encode(element) : element;
87						}
88					}
89				}
90			}
91			return null;
92		}
93	
94		/**
95		 * Mapping between a name and the pseudo property source.
96		 */
97		private abstract static class Mapping {
98	
99			private final String prefix;
100	
101			Mapping(String prefix) {
102				this.prefix = prefix;
103			}
104	
105			String getPrefix() {
106				return this.prefix;
107			}
108	
109			abstract @Nullable AnsiElement getElement(String postfix);
110	
111		}
112	
113		/**
114		 * {@link Mapping} for {@link AnsiElement} enums.
115		 */
116		private static class EnumMapping<E extends Enum<E> & AnsiElement> extends Mapping {
117	
118			private final Set<E> enums;
119	
120			EnumMapping(String prefix, Class<E> enumType) {
121				super(prefix);
122				this.enums = EnumSet.allOf(enumType);
123			}
124	
125			@Override
126			@Nullable AnsiElement getElement(String postfix) {
127				for (Enum<?> candidate : this.enums) {
128					if (candidate.name().equals(postfix)) {
129						return (AnsiElement) candidate;
130					}
131				}
132				return null;
133			}
134	
135		}
136	
137		/**
138		 * {@link Mapping} for {@link Ansi8BitColor}.
139		 */
140		private static class Ansi8BitColorMapping extends Mapping {
141	
142			private final IntFunction<Ansi8BitColor> factory;
143	
144			Ansi8BitColorMapping(String prefix, IntFunction<Ansi8BitColor> factory) {
145				super(prefix);
146				this.factory = factory;
147			}
148	
149			@Override
150			@Nullable AnsiElement getElement(String postfix) {
151				if (containsOnlyDigits(postfix)) {
152					try {
153						return this.factory.apply(Integer.parseInt(postfix));
154					}
155					catch (IllegalArgumentException ex) {
156						// Ignore
157					}
158				}
159				return null;
160			}
161	
162			private boolean containsOnlyDigits(String postfix) {
163				for (int i = 0; i < postfix.length(); i++) {
164					if (!Character.isDigit(postfix.charAt(i))) {
165						return false;
166					}
167				}
168				return !postfix.isEmpty();
169			}
170	
171		}
172	
173	}
