17	package org.springframework.boot.json;
18	
19	import java.util.ArrayList;
20	import java.util.Arrays;
21	import java.util.LinkedHashMap;
22	import java.util.List;
23	import java.util.Map;
24	
25	import org.jspecify.annotations.Nullable;
26	
27	import org.springframework.util.Assert;
28	import org.springframework.util.StringUtils;
29	
30	/**
31	 * Really basic JSON parser for when you have nothing else available. Comes with some
32	 * limitations with respect to the JSON specification (e.g. only supports String values),
33	 * so users will probably prefer to have a library handle things instead (Jackson or Snake
34	 * YAML are supported).
35	 *
36	 * @author Dave Syer
37	 * @author Jean de Klerk
38	 * @author Stephane Nicoll
39	 * @since 1.2.0
40	 * @see JsonParserFactory
41	 */
42	public class BasicJsonParser extends AbstractJsonParser {
43	
44		private static final int MAX_DEPTH = 1000;
45	
46		@Override
47		public Map<String, Object> parseMap(@Nullable String json) {
48			return tryParse(() -> parseMap(json, (jsonToParse) -> parseMapInternal(0, jsonToParse)), Exception.class);
49		}
50	
51		@Override
52		public List<Object> parseList(@Nullable String json) {
53			return tryParse(() -> parseList(json, (jsonToParse) -> parseListInternal(0, jsonToParse)), Exception.class);
54		}
55	
56		private List<Object> parseListInternal(int nesting, String json) {
57			List<Object> list = new ArrayList<>();
58			json = trimEdges(json, '[', ']').trim();
59			for (String value : tokenize(json)) {
60				list.add(parseInternal(nesting + 1, value));
61			}
62			return list;
63		}
64	
65		private Object parseInternal(int nesting, String json) {
66			if (nesting > MAX_DEPTH) {
67				throw new IllegalStateException("JSON is too deeply nested");
68			}
69			if (json.startsWith("[")) {
70				return parseListInternal(nesting + 1, json);
71			}
72			if (json.startsWith("{")) {
73				return parseMapInternal(nesting + 1, json);
74			}
75			if (json.startsWith("\"")) {
76				return trimEdges(json, '"', '"');
77			}
78			return parseNumber(json);
79		}
80	
81		private Map<String, Object> parseMapInternal(int nesting, String json) {
82			Map<String, Object> map = new LinkedHashMap<>();
83			json = trimEdges(json, '{', '}').trim();
84			for (String pair : tokenize(json)) {
85				String @Nullable [] split = StringUtils.split(pair, ":");
86				Assert.state(split != null, () -> "Unable to parse '%s'".formatted(pair));
87				@Nullable String[] rawElement = StringUtils.trimArrayElements(split);
88				String rawKey = rawElement[0];
89				String rawValue = rawElement[1];
90				Assert.state(rawKey != null, () -> "rawKey is null in '%s'".formatted(pair));
91				Assert.state(rawKey.startsWith("\"") && rawKey.endsWith("\""),
92						"Expecting double-quotes around field names");
93				String key = trimEdges(rawKey, '"', '"');
94				Assert.state(rawValue != null, () -> "rawValue is null in '%s'".formatted(pair));
95				Object value = parseInternal(nesting, rawValue);
96				map.put(key, value);
97			}
98			return map;
99		}
100	
101		private Object parseNumber(String json) {
102			try {
103				return Long.valueOf(json);
104			}
105			catch (NumberFormatException ex) {
106				try {
107					return Double.valueOf(json);
108				}
109				catch (NumberFormatException ex2) {
110					return json;
111				}
112			}
113		}
114	
115		private static String trimTrailingCharacter(String string, char c) {
116			if (!string.isEmpty() && string.charAt(string.length() - 1) == c) {
117				return string.substring(0, string.length() - 1);
118			}
119			return string;
120		}
121	
122		private static String trimLeadingCharacter(String string, char c) {
123			if (!string.isEmpty() && string.charAt(0) == c) {
124				return string.substring(1);
125			}
126			return string;
127		}
128	
129		private static String trimEdges(String string, char leadingChar, char trailingChar) {
130			return trimTrailingCharacter(trimLeadingCharacter(string, leadingChar), trailingChar);
131		}
132	
133		private List<String> tokenize(String json) {
134			List<String> list = new ArrayList<>();
135			Tracking tracking = new Tracking();
136			StringBuilder build = new StringBuilder();
137			int index = 0;
138			while (index < json.length()) {
139				char ch = json.charAt(index);
140				if (tracking.in(Tracked.ESCAPE)) {
141					build.append(ch);
142					index++;
143					tracking.set(Tracked.ESCAPE, 0);
144					continue;
145				}
146				switch (ch) {
147					case '{' -> tracking.update(Tracked.OBJECT, +1);
148					case '}' -> tracking.update(Tracked.OBJECT, -1);
149					case '[' -> tracking.update(Tracked.LIST, +1);
150					case ']' -> tracking.update(Tracked.LIST, -1);
151					case '"' -> tracking.toggle(Tracked.VALUE);
152				}
153				if (ch == ',' && !tracking.in(Tracked.OBJECT, Tracked.LIST, Tracked.VALUE)) {
154					list.add(build.toString());
155					build.setLength(0);
156				}
157				else if (ch == '\\') {
158					tracking.set(Tracked.ESCAPE, 1);
159				}
160				else {
161					build.append(ch);
162				}
163				index++;
164			}
165			if (!build.isEmpty()) {
166				list.add(build.toString().trim());
167			}
168			return list;
169		}
170	
171		private static final class Tracking {
172	
173			private final int[] counts = new int[Tracked.values().length];
174	
175			boolean in(Tracked... tracked) {
176				return Arrays.stream(tracked).mapToInt(this::get).anyMatch((i) -> i > 0);
177			}
178	
179			void toggle(Tracked tracked) {
180				set(tracked, (get(tracked) != 0) ? 0 : 1);
181			}
182	
183			void update(Tracked tracked, int delta) {
184				set(tracked, get(tracked) + delta);
185			}
186	
187			private int get(Tracked tracked) {
188				return this.counts[tracked.ordinal()];
189			}
190	
191			void set(Tracked tracked, int count) {
192				this.counts[tracked.ordinal()] = count;
193			}
194	
195		}
196	
197		private enum Tracked {
198	
199			OBJECT, LIST, VALUE, ESCAPE
200	
201		}
202	
203	}
